-- Real PostgreSQL role switching. Fixture Auth only; no hosted Supabase claim.
begin;
create schema test_support;
create function test_support.assert_true(condition boolean, label text) returns void
language plpgsql as $$ begin
  if condition is distinct from true then raise exception 'FAIL: %', label; end if;
  raise notice 'PASS: %', label;
end $$;
create function test_support.expect_error(statement text, expected_code text, label text) returns void
language plpgsql as $$
declare observed text;
begin
  begin execute statement;
  exception when others then get stacked diagnostics observed = returned_sqlstate; end;
  perform test_support.assert_true(observed = expected_code, label || ' expected ' || expected_code || ' got ' || coalesce(observed,'SUCCESS'));
end $$;
grant usage on schema test_support to anon, authenticated, service_role;
grant execute on all functions in schema test_support to anon, authenticated, service_role;
